1: #requires -Version 5.1
2: # 由环境注册表 registry.sqlite 生成多环境 nginx 站点片段（每 project x env 一个端口）。
3: # 用法: powershell -NoProfile -ExecutionPolicy Bypass -File gen_nginx_sites.ps1
4: $ErrorActionPreference = 'Stop'
5: [Console]::OutputEncoding = [System.Text.Encoding]::UTF8
6: # Python 在 Windows 下管道 stdout 默认走 ANSI(GBK)，中文路径会乱码；强制 UTF-8 输出
7: $env:PYTHONIOENCODING = 'utf-8'
8: 
9: $root    = 'D:\repository\skills\deploy-env'
10: $db      = Join-Path $root 'registry.sqlite'
11: $siteDir = Join-Path $root 'env-sites'
12: $py      = 'C:\Program Files\Python310\python.exe'
13: 
14: if (-not (Test-Path -LiteralPath $db)) { throw "registry.sqlite 不存在: $db" }
15: 
16: # ---- 1) 读注册表（python 内置 sqlite3，无 sqlite3 CLI；TSV 输出）----
17: $pyCode = @'
18: import sqlite3
19: con = sqlite3.connect(r'__DB__')
20: for r in con.execute('SELECT project,env,port,dist_root,backend_gateway,status FROM env_registry ORDER BY project,port'):
21:     print('\t'.join(str(x) for x in r))
22: con.close()
23: '@
24: 
25: $pyCode = $pyCode.Replace('__DB__', $db)
26: $tsv = & $py -c $pyCode
27: if ($LASTEXITCODE -ne 0) { throw "读取注册表失败 (python exit=$LASTEXITCODE)" }
28: 
29: $rows = @()
30: foreach ($line in $tsv) {
31:     if ([string]::IsNullOrWhiteSpace($line)) { continue }
32:     $c = $line -split "`t"
33:     if ($c.Count -lt 6) { throw "注册表行格式异常: $line" }
34:     $rows += [pscustomobject]@{
35:         Project = $c[0]; Env = $c[1]; Port = [int]$c[2]
36:         Dist = $c[3]; Gateway = $c[4]; Status = $c[5]
37:     }
38: }
39: if ($rows.Count -eq 0) { throw '注册表为空，未生成任何站点' }
40: 
41: # ---- 2) 端口冲突双保险（之二）：生成时重复端口报错 ----
42: $dups = $rows | Group-Object Port | Where-Object { $_.Count -gt 1 }
43: if ($dups) {
44:     throw "端口冲突（注册表存在重复端口）: " + (($dups | ForEach-Object { $_.Name }) -join ',')
45: }
46: 
47: # ---- 3) 片段模板（单引号 here-string，nginx 变量原样保留，占位符替换）----
48: $portalApi = @'
49:     # 静态资源缓存
50:     location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|map|json|pdf)$ {
51:         expires 7d;
52:         add_header Cache-Control "public" always;
53:         add_header X-Proxy-Target-Url "__GATEWAY__$request_uri" always;
54:         try_files $uri =404;
55:     }
56:     # 业务 API（统一打到本环境网关）
57:     location /api/v2.0/  { proxy_pass __GATEWAY__; }
58:     location /api/v3.0/  { proxy_pass __GATEWAY__; }
59:     location /v3.0/      { proxy_pass __GATEWAY__; }
60:     location /zhi2/      { proxy_pass __GATEWAY__; }
61:     location /zhi2-dev/  { proxy_pass __GATEWAY__; }
62:     location /zhi2-test/ { proxy_pass __GATEWAY__; }
63: '@
64: $fdcApi = @'
65:     # 静态资源缓存
66:     location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|map|json|xlsx)$ {
67:         expires 7d;
68:         add_header Cache-Control "public" always;
69:         try_files $uri =404;
70:     }
71:     # 业务 API：/api/v2.0 → 网关原生路径（验证码等；恒等 rewrite 保 /api/v2.0 前缀）
72:     location /api/v2.0/ {
73:         rewrite ^/api/v2.0/(.*)$ /api/v2.0/$1 break;
74:         proxy_pass __GATEWAY__;
75:     }
76:     #
