84: '@
85: $serverTpl = @'
86: # AUTO-GENERATED by gen_nginx_sites.ps1 — DO NOT EDIT BY HAND
87: # project=__PROJECT__  env=__ENV__  port=__PORT__  gateway=__GATEWAY__
88: server {
89:     listen __PORT__;
90:     server_name _;
91:     root "__DIST__";
92:     index index.html;
93:     charset utf-8;
94:     client_max_body_size 100m;
95: 
96:     proxy_http_version 1.1;
97:     proxy_set_header Connection "";
98:     proxy_set_header Host __GATEWAY_HOST__;
99:     proxy_set_header X-Real-IP $remote_addr;
100:     proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
101:     proxy_set_header X-Forwarded-Proto $scheme;
102:     proxy_connect_timeout 60s;
103:     proxy_send_timeout 120s;
104:     proxy_read_timeout 120s;
105: 
106: __API_LOCS__
107: 
108:     # SPA history 回退
109:     location / { try_files $uri $uri/ /index.html; }
110:     # 禁止访问隐藏文件
111:     location ~ /\. { deny all; }
112: }
113: '@
114: 
115: # ---- 4) 生成片段 ----
116: New-Item -ItemType Directory -Force -Path $siteDir | Out-Null
117: # 清理旧的生成片段，避免删除环境后残留
118: Get-ChildItem -LiteralPath $siteDir -Filter '*.conf' -File -ErrorAction SilentlyContinue | Remove-Item -Force
119: 
120: $enc = [System.Text.UTF8Encoding]::new($false)  # 无 BOM，避免 nginx 报 unknown directive
121: $generated = @()
122: foreach ($r in $rows) {
123:     if ($r.Status -ne 'enabled') { continue }
124:     # 空网关无法生成有效 proxy_pass（nginx -t 会全盘失败），跳过该片段
125:     if ([string]::IsNullOrWhiteSpace($r.Gateway)) { Write-Output ("SKIP empty gateway: " + $r.Project + '/' + $r.Env); continue }
126:     $apiTpl = if ($r.Project -eq 'portal') { $portalApi } else { $fdcApi }
127:     $apiLocs = $apiTpl.Replace('__GATEWAY__', $r.Gateway)
128:     # 网关按 Host 路由：Host 必须是网关域名，传 $host(localhost) 会 500 (x-proxy-url 空)
129:     $gwHost = ([uri]$r.Gateway).Host
130:     if ([string]::IsNullOrWhiteSpace($gwHost)) { $gwHost = '$host' }
131:     $conf = $serverTpl.Replace('__PROJECT__', $r.Project).Replace('__ENV__', $r.Env).Replace('__PORT__', [string]$r.Port).Replace('__GATEWAY__', $r.Gateway).Replace('__GATEWAY_HOST__', $gwHost).Replace('__DIST__', $r.Dist).Replace('__API_LOCS__', $apiLocs)
132:     $file = Join-Path $siteDir ("{0}-{1}.conf" -f $r.Project, $r.Env)
133:     [System.IO.File]::WriteAllText($file, $conf, $enc)
134:     $generated += $file
135: }
136: 
137: Write-Output ("GENERATED={0}" -f $generated.Count)
138: $generated | ForEach-Object { Write-Output ("  " + $_) }

